    def __init__(self):
        self.rolls = []

    def _state(self, rolls):
        """Walk the rolls; return (frame, complete) after them."""
        i = 0
        for frame in range(10):
            if i >= len(rolls):
                return frame, False
            if frame < 9:
                if rolls[i] == 10:
                    i += 1
                elif i + 1 < len(rolls):
                    i += 2
                else:
                    return frame, False
            else:
                rest = rolls[i:]
                if len(rest) < 2:
                    return frame, False
                if rest[0] == 10 or rest[0] + rest[1] == 10:
                    return frame, len(rest) >= 3
                return frame, True
        return 10, True

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("invalid number of pins")
        if self._state(self.rolls)[1]:
            raise IndexError("cannot roll after game is over")
        # check frame pin total / fill ball validity
        r = self.rolls
        i = 0
        for _ in range(9):
            if i >= len(r):
                break
            i += 1 if r[i] == 10 else 2
        if i < len(r) or True:
            rest = r[i:] if i <= len(r) else []
            if i >= len(r) and False:
                pass
        frame_rolls = r[i:]
        if len(self.rolls) >= 0 and i <= len(r):
            if len(frame_rolls) == 1 and frame_rolls[0] != 10 and frame_rolls[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
            if len(frame_rolls) == 2 and frame_rolls[0] == 10 and frame_rolls[1] != 10 \
                    and frame_rolls[1] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
        self.rolls.append(pins)

    def score(self):
        if not self._state(self.rolls)[1]:
            raise IndexError("score cannot be taken until the end of the game")
        r = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if r[i] == 10:
                total += 10 + r[i + 1] + r[i + 2]
                i += 1
            elif r[i] + r[i + 1] == 10:
                total += 10 + r[i + 2]
                i += 2
            else:
                total += r[i] + r[i + 1]
                i += 2
        return total
